import{_ as a,c as r,o as e,a3 as o}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"自定义","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/customize.md","filePath":"zh-CN/guide/customize.md","lastUpdated":1787284674000}'),n={name:"zh-CN/guide/customize.md"};function l(i,t,s,d,g,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="自定义" tabindex="-1">自定义 <a class="header-anchor" href="#自定义" aria-label="Permalink to &quot;自定义&quot;">​</a></h1><p>让 ClipboxAI 按照你的方式工作。本指南涵盖你可以调整的各项设置。</p><h2 id="通用-general" tabindex="-1">通用（General） <a class="header-anchor" href="#通用-general" aria-label="Permalink to &quot;通用（General）&quot;">​</a></h2><p>打开 <strong>ClipboxAI → 设置（Settings）</strong>（或按 <code>Cmd+,</code>）。</p><ul><li><strong>语言（Language）</strong>：English、简体中文、繁體中文、日本語。</li><li><strong>登录时启动（Launch at Login）</strong>：登录时自动启动应用。</li><li><strong>外观（Appearance）</strong>：浅色、深色，或跟随系统（System，跟随 macOS）。</li></ul><h2 id="ai-配置" tabindex="-1">AI 配置 <a class="header-anchor" href="#ai-配置" aria-label="Permalink to &quot;AI 配置&quot;">​</a></h2><p>在 <strong>设置 → AI（Settings → AI）</strong> 中设置云端 AI：</p><table tabindex="0"><thead><tr><th>设置</th><th>选项</th><th>说明</th></tr></thead><tbody><tr><td><strong>Provider</strong></td><td>DeepSeek, MiniMax, GLM, Kimi, Mistral, Ollama, OpenAI, Anthropic, Gemini</td><td>要调用的 OpenAI 兼容服务</td></tr><tr><td><strong>API Key</strong></td><td>你的 key</td><td>保存在 <strong>Keychain</strong> 中，绝不以明文写入磁盘</td></tr><tr><td><strong>Model</strong></td><td>各提供商不同</td><td>用于 AI 操作的模型</td></tr><tr><td><strong>Cloud AI enabled</strong></td><td>开 / 关</td><td>将剪贴内容发送到云端的总开关</td></tr></tbody></table><p>云端 AI <strong>默认关闭</strong>。启用后，你的剪贴内容只会发送给所配置的提供商。</p><h2 id="操作-actions" tabindex="-1">操作（Actions） <a class="header-anchor" href="#操作-actions" aria-label="Permalink to &quot;操作（Actions）&quot;">​</a></h2><p>自定义工具的行为方式：</p><ul><li><strong>输出时自动运行（Auto-run on output）</strong>：开启后，所选工具会在你复制的瞬间自动运行。</li><li><strong>排除的应用（Excluded apps）</strong>：此处的应用会被剪贴板监控与自动运行跳过（例如密码管理器）。</li><li><strong>工具顺序（Tool order）</strong>：在 AI 工具窗口中，拖动已安装的工具以重新排序；你的顺序会被记住。</li></ul><h2 id="隐私-privacy" tabindex="-1">隐私（Privacy） <a class="header-anchor" href="#隐私-privacy" aria-label="Permalink to &quot;隐私（Privacy）&quot;">​</a></h2><p>打开 <strong>设置 → 隐私（Settings → Privacy）</strong>：</p><ul><li><strong>云端 AI 选择性开启（Cloud AI opt-in）</strong>：将数据发送给提供商的总开关。</li><li><strong>排除的应用（Excluded apps）</strong>：阻止特定应用被捕获。</li><li><strong>历史记录控制（History controls）</strong>：管理剪贴内容在你的设备上保留多长时间。</li></ul><p>所有历史记录均保留在本地。我们不会上传剪贴内容，也不会运行分析。</p><h2 id="操作市场-marketplace" tabindex="-1">操作市场（Marketplace） <a class="header-anchor" href="#操作市场-marketplace" aria-label="Permalink to &quot;操作市场（Marketplace）&quot;">​</a></h2><p>管理已安装的操作：</p><ul><li><strong>浏览（Browse）</strong>：从 AI 工具窗口或站点打开 <strong>Marketplace</strong>。</li><li><strong>安装（Install）</strong>：在某个操作上点击 <strong>Install</strong>，通过深链接添加它。</li><li><strong>移除（Remove）</strong>：从你的 <strong>已安装（Installed）</strong> 列表卸载某个操作。</li></ul><h2 id="菜单栏" tabindex="-1">菜单栏 <a class="header-anchor" href="#菜单栏" aria-label="Permalink to &quot;菜单栏&quot;">​</a></h2><ul><li><strong>在菜单栏中显示（Show in menu bar）</strong>：启用 / 禁用托盘图标。</li><li><strong>关闭时退出（Quit on close）</strong>：选择应用是否在后台继续运行。</li></ul><h2 id="小贴士" tabindex="-1">小贴士 <a class="header-anchor" href="#小贴士" aria-label="Permalink to &quot;小贴士&quot;">​</a></h2><ul><li>在需要之前保持云端 AI 关闭——本地工具已覆盖大多数日常整理需求。</li><li>将密码管理器和启用安全输入的应用加入 <strong>排除的应用（Excluded apps）</strong>，确保机密内容绝不会被捕获。</li><li>将自动运行与本地工具搭配，实现每次复制时的免手动文本清理。</li></ul>',23)])])}const p=a(n,[["render",l]]);export{u as __pageData,p as default};
